style.css:
@-moz-document domain("youtube.com") {
/* Background */
    body {
        background: url('https://wallpapercave.com/wp/wp8916489.jpg') no-repeat center center fixed !important;
        background-size: cover !important;
    }
    
    /* General Styling */
    #page-manager, ytd-app {
        background-color: rgba(173, 216, 230, 0.9) !important; /* Light blue overlay */
    }
    
    /* Video player */
    ytd-watch-flexy {
        background: rgba(240, 248, 255, 0.9) !important; /* Light airy blue */
    }
    
    /* Top Bar */
    #masthead-container {
        background-color: rgba(135, 206, 250, 0.8) !important;
    }
    
    /* Sidebar */
    ytd-guide-section-renderer, ytd-guide-renderer {
        background-color: rgba(176, 224, 230, 0.9) !important;
    }
    
    /* Buttons and Text */
    ytd-button-renderer, a {
        color: #1e90ff !important; /* Deep sky blue */
    }
    
    /* Hide Ads (optional) */
    #player-ads, .ytp-ad-module, .ad-showing {
        display: none !important;
    }
}
